import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { orderAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const STATUS_COLORS = {
  'Pending': '#f59e0b',
  'Confirmed': '#3b82f6',
  'Out for Delivery': '#8b5cf6',
  'Delivered': '#16a34a',
  'Cancelled': '#dc2626',
};

const OrderHistoryPage = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) { navigate('/login'); return; }
    orderAPI.getMyOrders().then(res => { setOrders(res.data.orders); setLoading(false); }).catch(() => setLoading(false));
  }, [user]);

  const printInvoice = (order) => {
    const w = window.open('', '_blank');
    w.document.write(`<html><head><title>Invoice ${order.invoiceNumber}</title><style>body{font-family:Arial;padding:30px;max-width:600px;margin:0 auto}h1{color:#16a34a}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left}th{background:#f0fdf4}</style></head><body>
      <h1>🌿 Desi2Door</h1><h2>Invoice: ${order.invoiceNumber}</h2>
      <p><b>Date:</b> ${new Date(order.createdAt).toLocaleDateString('en-IN')}</p>
      <p><b>Customer:</b> ${order.customerName} | ${order.customerPhone}</p>
      <p><b>Delivery:</b> ${order.address.street}, ${order.address.city} - ${order.address.pincode}</p>
      <p><b>Slot:</b> ${order.deliverySlot || 'N/A'} | <b>Status:</b> ${order.status}</p>
      <table><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr>
      ${order.items.map(i => `<tr><td>${i.name}</td><td>${i.quantity}</td><td>₹${i.price}</td><td>₹${i.price*i.quantity}</td></tr>`).join('')}
      </table><br/><b style="font-size:18px;color:#16a34a">Total: ₹${order.totalAmount}</b>
      <p>Payment: Cash on Delivery</p></body></html>`);
    w.document.close(); w.print();
  };

  if (loading) return <div className="spinner" />;

  return (
    <div className="page-fade">
      <div className="page-header">
        <div className="container">
          <h1>📦 My Orders</h1>
          <p style={{ marginTop: 4, opacity: 0.8 }}>Track your orders here</p>
        </div>
      </div>
      <div className="container">
        {orders.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 20px' }}>
            <div style={{ fontSize: 70, marginBottom: 16 }}>📦</div>
            <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 24, color: 'var(--gray-600)', marginBottom: 12 }}>No orders yet</h2>
            <p style={{ color: 'var(--gray-400)', marginBottom: 24 }}>Start shopping to see your orders here!</p>
            <Link to="/shop" className="btn-primary">🛒 Shop Now</Link>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {orders.map(order => (
              <div key={order._id} style={{ background: 'white', borderRadius: 16, padding: 20, boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16, flexWrap: 'wrap', gap: 10 }}>
                  <div>
                    <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 17, color: 'var(--gray-800)' }}>
                      {order.invoiceNumber}
                    </div>
                    <div style={{ fontSize: 13, color: 'var(--gray-400)', marginTop: 2 }}>
                      {new Date(order.createdAt).toLocaleDateString('en-IN', { dateStyle: 'long' })} | ⏰ {order.deliverySlot || 'N/A'}
                    </div>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <span style={{ background: STATUS_COLORS[order.status] + '20', color: STATUS_COLORS[order.status], fontWeight: 700, fontSize: 13, padding: '4px 12px', borderRadius: 20 }}>
                      ● {order.status}
                    </span>
                    <button onClick={() => printInvoice(order)} style={{ background: 'var(--gray-100)', border: 'none', borderRadius: 8, padding: '6px 12px', fontSize: 13, cursor: 'pointer', fontWeight: 600 }}>
                      🖨️ Invoice
                    </button>
                  </div>
                </div>

                <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
                  {order.items.map((item, i) => (
                    <span key={i} style={{ background: 'var(--gray-50)', border: '1px solid var(--gray-200)', borderRadius: 8, padding: '4px 10px', fontSize: 13, color: 'var(--gray-700)' }}>
                      {item.name} ×{item.quantity}
                    </span>
                  ))}
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid var(--gray-100)', paddingTop: 12 }}>
                  <div style={{ fontSize: 13, color: 'var(--gray-500)' }}>
                    📍 {order.address.city}, {order.address.state}
                  </div>
                  <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 20, color: 'var(--green)' }}>
                    ₹{order.totalAmount}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default OrderHistoryPage;
